<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\User\Infrastructure\Driven;

use Override;
use DateInterval;
use DateTimeImmutable;
use Civi\Lughauth\Shared\Security\AesCypherService;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Features\Access\User\Domain\User;
use Civi\Lughauth\Features\Access\Tenant\Domain\Tenant;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientReadGateway;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityFilter;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityReadGateway;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityFilter;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityReadGateway;
use Civi\Lughauth\Features\Access\Role\Domain\Gateway\RoleReadGateway;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\Gateway\RelyingPartyReadGateway;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\Gateway\TenantConfigReadGateway;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserWriteGateway;
use Civi\Lughauth\Features\Access\UserAcceptedTermnsOfUse\Domain\Gateway\UserAcceptedTermnsOfUseReadGateway;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\Oidc\User\Domain\Gateway\LoginGateway;
use Civi\Lughauth\Features\Oidc\Common\Infrastructure\Driven\UserLoaderAdapter;
use Civi\Lughauth\Features\Oidc\Scopes\Application\Usecase\ScopesConsentUsecase;

class LoginAdapter implements LoginGateway
{
    use LoggerAwareTrait;

    public function __construct(
        private readonly AesCypherService $cypher,
        private readonly UserLoaderAdapter $users,
        private readonly TenantConfigReadGateway $configs,
        private readonly UserAcceptedTermnsOfUseReadGateway $userTerms,
        private readonly PlatformIdentityReadGateway $platformIdentities,
        private readonly ClientIdentityReadGateway $clientIdentities,
        private readonly TrustedClientReadGateway $clients,
        private readonly RelyingPartyReadGateway $parties,
        private readonly UserWriteGateway $writeUsers,
        private readonly RoleReadGateway $roles,
        private readonly ScopesConsentUsecase $scopesConsent,
    ) {
    }

    #[Override]
    public function fillPreLoadById(
        string $tenant,
        AuthenticationRequest $client,
        ChallengesState $challenges
    ): AuthenticationResult {
        $username = $challenges->username ?? '';
        $theTenant = $this->users->checkTenant($tenant, $username);
        $theUser = $this->users->checkUserSubjet($theTenant, $username);
        return new AuthenticationResult(
            valid: true,
            id: $theUser->uid(),
            name: $theUser->getName(),
            email: $theUser->getEmail(),
            tenant: $theTenant->uid(),
            tenantName: $theTenant->getName(),
            scope: $client->scope,
            audiences: $client->audiences,
            roles: $this->loadRoles($client, $theTenant, $theUser),
            groups: $this->loadGroups(),
        );
    }

    #[Override]
    public function fillPreAuthenticated(
        string $tenant,
        AuthenticationRequest $client,
        ChallengesState $challenges
    ): AuthenticationResult {
        $username = $challenges->username ?? '';
        $theTenant = $this->users->checkTenant($tenant, $username);
        $theUser = $this->users->checkUser($theTenant, $username);
        return new AuthenticationResult(
            valid: true,
            id: $theUser->uid(),
            name: $theUser->getName(),
            email: $theUser->getEmail(),
            tenant: $theTenant->uid(),
            tenantName: $theTenant->getName(),
            scope: $client->scope,
            audiences: $client->audiences,
            roles: $this->loadRoles($client, $theTenant, $theUser),
            groups: $this->loadGroups(),
        );
    }

    #[Override]
    public function validatedUserData(
        string $tenant,
        string $username,
        string $password,
        AuthenticationRequest $client
    ): AuthenticationResult {
        $theTenant = $this->users->checkTenant($tenant, $username);
        $theUser = $this->users->checkUser($theTenant, $username);
        $this->checkPassword($theTenant, $theUser, $password);
        if ($temp = $this->checkTemporalPassword($theTenant, $theUser)) {
            return $temp;
        }
        if ($reqMfa = $this->checkMfaConfigurationRequired($theTenant, $theUser)) {
            return $reqMfa;
        }
        if ($mfa = $this->checkMfa($theTenant, $theUser)) {
            return $mfa;
        }
        if ($terms = $this->checkTerms($theTenant, $theUser, $client->audiences)) {
            return $terms;
        }
        if ($scopes = $this->checkScopesConsent($theTenant, $theUser, $client)) {
            return $scopes;
        }
        $this->markLoginOk($theUser);
        return new AuthenticationResult(
            valid: true,
            id: $theUser->uid(),
            name: $theUser->getName(),
            email: $theUser->getEmail(),
            tenant: $theTenant->uid(),
            tenantName: $theTenant->getName(),
            scope: $client->scope,
            audiences: $client->audiences,
            roles: $this->loadRoles($client, $theTenant, $theUser),
            groups: $this->loadGroups(),
        );
    }

    /**
     * @return void
     */
    private function checkPassword(Tenant $tenant, User $user, string $password)
    {
        if ($user->getPlainPassword($this->cypher) !== $password) {
            $this->markLoginFail($user);
            throw new LoginException(auth: AuthenticationResult::wrongCredentials($tenant->getName(), $user->getName()));
        }
    }

    private function checkTemporalPassword(Tenant $tenant, User $user): ?AuthenticationResult
    {
        return $user->isTemporalPassword() ? AuthenticationResult::newPasswordRequired() : null;
    }

    private function checkTerms(Tenant $tenant, User $user, array $audiences): ?AuthenticationResult
    {
        $terms = $this->users->loadTenantTerms($tenant, $audiences);
        foreach ($terms as $term) {
            $accepted = $this->userTerms->findOneByUserAndConditions($user, $term);
            if (!$accepted) {
                return AuthenticationResult::consentRequired($term->getText());
            }
        }
        return null;
    }

    private function checkScopesConsent(Tenant $tenant, User $user, AuthenticationRequest $client): ?AuthenticationResult
    {
        $pending = $this->scopesConsent->pendingScopes(
            $tenant->getName(),
            $user->getName(),
            $client->client->id,
            $client->scope
        );
        return $pending ? AuthenticationResult::scopesConsentRequired() : null;
    }

    private function checkMfaConfigurationRequired(Tenant $tenant, User $user): ?AuthenticationResult
    {
        if ($user->getSecondFactorSeed()) {
            return null;
        }
        if ($user->isUseSecondFactors()) {
            return AuthenticationResult::newMfaRequired();
        }
        $conf = $this->configs->findOneByTenant($tenant);
        return ($conf && $conf->isForceMfa()) ? AuthenticationResult::newMfaRequired() : null;
    }

    private function checkMfa(Tenant $tenant, User $user): ?AuthenticationResult
    {
        return ($user->getSecondFactorSeed() && $user->isUseSecondFactors()) ? AuthenticationResult::mfaRequired() : null;
    }

    private function markLoginFail(User $user): void
    {
        $this->markLogin($user, true);
    }

    private function markLoginOk(User $user): void
    {
        $this->markLogin($user, false);
    }

    private function markLogin(User $user, bool $fail): void
    {
        $limit = 3;
        $code = $this->users->userCodeForUpdate($user);
        if ($fail) {
            if ($code->getFailedLoginAttempts() >= $limit) {
                $this->writeUsers->update($user, $user->block((new DateTimeImmutable())->add(new DateInterval("PT6H"))));
                $this->users->updateCode($code->markLoginBlock());
            } else {
                $this->users->updateCode($code->markLoginFail());
            }
        } else {
            $this->users->updateCode($code->markLoginOk());
        }
    }

    /**
     * @return array[]
     *
     * @psalm-return array<list<mixed>>
     */
    private function loadRoles(AuthenticationRequest $client, Tenant $tenant, User $user): array
    {
        $main = $tenant->getName() === 'main';
        $roles = [];
        // Tengo roles para cualquier audiencia
        $forAll = [];
        $this->clientRolesFromIdentity(new ClientIdentityFilter(user: $user)->withForAllAudiences(true), $main, $forAll);
        $this->platformRolesFromIdentity(new PlatformIdentityFilter(user: $user)->withForAllAudiences(true), $main, $forAll);
        if ($client->audiences) {
            foreach ($client->audiences as $audience) {
                $roles[$audience] = $forAll;
                if ($from = $this->clients->findOneByCode($audience)) {
                    $this->platformRolesFromIdentity(new PlatformIdentityFilter(
                        user: $user,
                        trustedClient: $from
                    ), $main, $roles[$audience]);
                }
                if ($from = $this->parties->findOneByCode($audience)) {
                    $this->platformRolesFromIdentity(new PlatformIdentityFilter(
                        user: $user,
                        relyingParty: $from
                    ), $main, $roles[$audience]);
                    $this->clientRolesFromIdentity(new ClientIdentityFilter(
                        user: $user,
                        relyingParty: $from
                    ), $main, $roles[$audience]);
                }
            }
        }
        return $roles;
    }

    private function platformRolesFromIdentity(PlatformIdentityFilter $identityFilter, bool $main, array &$roles): void
    {
        if ($tc = $this->platformIdentities->retrieve($identityFilter)) {
            $hisRoles = $tc->getRoles();
            if (null !== $hisRoles) {
                foreach ($hisRoles as $role) {
                    $ref = $role->getRole();
                    $theRole = $this->roles->resolve($ref);
                    if ($theRole) {
                        $roleName = 'platform:' . strtolower($theRole->getName());
                        if (!in_array($roleName, $roles, true)) {
                            $roles[] =   $roleName;
                        }
                    }
                }
            }
        }
    }

    private function clientRolesFromIdentity(ClientIdentityFilter $identityFilter, bool $main, array &$roles): void
    {
        if ($tc = $this->clientIdentities->retrieve($identityFilter)) {
            $hisRoles = $tc->getRoles();
            if (null !== $hisRoles) {
                $roles = explode(",", $hisRoles);
                foreach ($roles as $role) {
                    $roleName = str_replace(':', '-', strtolower($role));
                    if (!in_array($roleName, $roles, true)) {
                        $roles[] = $roleName;
                    }
                }
            }
        }
    }

    /**
     * @psalm-return array<never, never>
     */
    private function loadGroups(): array
    {
        return [];
    }
}
